Body:
While this gets added to models.dev, you can add the following to your **opencode.json** configuration (if you have Z.AI Coding Plan) and use it right away:

``` json
  "provider": {
    "zai-latest": {
      "npm": "@ai-sdk/openai-compatible",
      "name": "Latest Z.AI",
      "options": {
        "baseURL": "https://api.z.ai/api/coding/paas/v4",
        "apiKey": "YOUR_API_KEY_HERE"
      },
      "models": {
        "glm-5.2": {
          "name": "GLM 5.2",
          "limit": {
            "context": 1000000,
            "output": 131072
          },
          "options": {
            "reasoningEffort": "max"
          }
        }
      }
    }
  }
```
